from pathlib import Path
p = Path('features/plants/components/PlantDetailPanels.tsx')
s = p.read_text(encoding='utf-8').replace('StyleSheet, Text, View', 'StyleSheet, Text, View, Linking')
s = s.replace("weather.forecasted ? 'Forecast' : weather.observationUtc", "weather.forecasted ? 'Forecast' : weather.temperatureBasis === 'model' ? 'Modelled conditions' : weather.observationUtc")
s = s.replace('Observation: {new Date', "{weather.temperatureBasis === 'model' ? 'Model valid at' : 'Observation'}: {new Date")
s = s.replace("['Rain', metric(weather.rainfall", "[weather.rainIntervalSeconds ? `Rain (${weather.rainIntervalSeconds / 60} min)` : 'Rain', metric(weather.rainfall")
s = s.replace("['UV index', metric", "[weather.temperatureBasis === 'model' && !weather.forecasted ? 'Recent hourly mean UV' : 'UV index', metric")
s = s.replace("['Forecast morning', metric", "[weather.temperatureBasis === 'model' ? 'Forecast at 06:00' : 'Forecast morning', metric")
s = s.replace("['Forecast evening', metric", "[weather.temperatureBasis === 'model' ? 'Forecast at 18:00' : 'Forecast evening', metric")
s = s.replace("['Forecast night', metric", "[weather.temperatureBasis === 'model' ? 'Forecast at 23:00' : 'Forecast night', metric")
s = s.replace("['Night humidity', metric", "[weather.temperatureBasis === 'model' ? 'Forecast night mean RH' : 'Night humidity', metric")
s = s.replace("card.metrics.experimental ? 'On-device experiment · Assumed weather and test profile'", "card.metrics.experimental ? card.metrics.weatherDriven ? 'On-device experiment · Model weather and test profile' : 'On-device experiment · Assumed weather and test profile'")
s = s.replace('    {compact ? <>', '    {weather.qualityNotes?.map((note, i) => <Text key={i} selectable style={{ color: theme.muted, fontSize: 12, marginTop: 6 }}>{note}</Text>)}\n    {compact ? <>')
s = s.replace("{weather.source && <Text", "{weather.source === 'Open-Meteo' && <GrowPress accessibilityRole=\"link\" accessibilityLabel=\"Weather data by Open-Meteo\" onPress={() => { void Linking.openURL('https://open-meteo.com/'); }}><Text style={{ color: theme.water, fontSize: 12, marginTop: 12 }}>Weather data by Open-Meteo · CC BY 4.0 · model estimates; displayed summaries derived by this app</Text></GrowPress>}{weather.source && <Text")
p.write_text(s, encoding='utf-8')
p = Path('lib/careAlgorithm/careDiagnostics.ts')
s = p.read_text(encoding='utf-8').replace("value: `Assumed constant ET0", "value: inputs.weatherMode === 'open-meteo' ? 'Open-Meteo hourly model ET0 and liquid rain. Current-hour timing is bounded conditionally; not field measurements.' : `Assumed constant ET0")
s = s.replace("    for (const scenario of e.water", "    if (inputs?.weatherMode === 'open-meteo') entries.push({ label: 'Weather acquired (UTC)', value: stamp(inputs.weatherRetrievedUtc) });\n    for (const scenario of e.water")
s = s.replace('Choose Dry test or Rain test', 'Choose Use Open-Meteo weather, Dry test or Rain test')
p.write_text(s, encoding='utf-8')
